/**
 * Routed hub handler (RFC 0001 §Decisions).
 *
 * Wraps the filesystem HubHandler and routes each call by the workspace's
 * backend: filesystem workspaces flow to the inner handler byte-for-byte
 * unchanged; workspaces with an active celld route become cell commands and
 * queries. Routing happens at this high-level boundary deliberately — there
 * is no record-level storage adapter, so claims, membership, impacts,
 * receipts, and events commit together inside one cell transaction.
 *
 * Dependency direction: src/celld -> src/hub only (architecture-tested).
 * The hub never learns this module exists; composition injects it in
 * src/index.ts / server-factory.
 */

import { randomUUID } from 'node:crypto';
import type { HubEvent, HubHandler } from '../hub/hub-handler.js';
import { commandPayloadHash, type JsonValue } from './canonical-json.js';
import {
  commandMetadataV1Schema,
  COMMAND_SCHEMA_VERSION,
  isCelldMutation,
  isCelldSupportedOperation,
  CELLD_NEW_OPERATIONS,
  type CellCommandResult,
  type CommandMetadataV1,
  type HubCommandV1,
} from './contracts.js';
import { CelldError, rejection } from './errors.js';
import type { BackendRegistry } from './backend-registry.js';
import type { CellTransport } from './client.js';

export interface RoutedHubHandlerOptions {
  inner: HubHandler;
  transport: CellTransport;
  registry: BackendRegistry;
  /** SSE hint sink — same shape the inner handler emits; celld events carry
   *  the durable eventId inside `data` and consumers dedupe by it. */
  onEvent?: (event: HubEvent) => void;
}

interface PersistedCellEvent {
  eventId?: unknown;
  sequence?: unknown;
  aggregateRevision?: unknown;
  type?: unknown;
  data?: unknown;
  occurredAt?: unknown;
}

const NEW_OPERATIONS: ReadonlySet<string> = new Set(CELLD_NEW_OPERATIONS);

export function createRoutedHubHandler(options: RoutedHubHandlerOptions): HubHandler {
  const { inner, transport, registry, onEvent } = options;

  function emitCellEvents(workspaceId: string, commandId: string, events: unknown): void {
    if (onEvent === undefined || !Array.isArray(events)) return;
    for (const raw of events as PersistedCellEvent[]) {
      if (typeof raw?.type !== 'string') continue;
      onEvent({
        // The cell's event vocabulary is a subset of HubEventType plus the
        // four coordination types added alongside this canary; the parity
        // check pins both unions.
        type: raw.type as HubEvent['type'],
        workspaceId,
        data: {
          ...(typeof raw.data === 'object' && raw.data !== null ? (raw.data as Record<string, unknown>) : {}),
          eventId: raw.eventId,
          sequence: raw.sequence,
          aggregateRevision: raw.aggregateRevision,
          commandId,
        },
      });
    }
  }

  function requireCommandMetadata(args: Record<string, unknown>, operation: string): CommandMetadataV1 {
    const parsed = commandMetadataV1Schema.safeParse(args.command);
    if (!parsed.success) {
      throw new CelldError(
        rejection(
          'VALIDATION_FAILED',
          `${operation} on a celld workspace requires a 'command' object (CommandMetadataV1 with at least an id); see RFC 0001`,
          { issue: parsed.error.issues[0]?.message ?? 'missing' },
        ),
      );
    }
    return parsed.data;
  }

  async function buildCommand(
    operation: string,
    workspaceId: string,
    agentId: string,
    metadata: CommandMetadataV1,
    payload: Record<string, JsonValue>,
  ): Promise<HubCommandV1> {
    const command: HubCommandV1 = {
      schemaVersion: COMMAND_SCHEMA_VERSION,
      commandId: metadata.id,
      operation,
      workspaceId,
      actor: {
        agentId,
        ...(metadata.promptVersion !== undefined ? { promptVersion: metadata.promptVersion } : {}),
      },
      issuedAt: new Date().toISOString(),
      context: {
        ...(metadata.teamRunId !== undefined ? { teamRunId: metadata.teamRunId } : {}),
        ...(metadata.nativeTaskId !== undefined ? { nativeTaskId: metadata.nativeTaskId } : {}),
        ...(metadata.processRunId !== undefined ? { processRunId: metadata.processRunId } : {}),
      },
      payload,
      payloadHash: '',
    };
    if (metadata.expectedRevision !== undefined) command.expectedRevision = metadata.expectedRevision;
    if (metadata.correlationId !== undefined) command.correlationId = metadata.correlationId;
    if (metadata.causationId !== undefined) command.causationId = metadata.causationId;
    command.payloadHash = await commandPayloadHash(command);
    return command;
  }

  function coordinationOf(result: CellCommandResult, commandId?: string): Record<string, JsonValue> {
    const coordination: Record<string, JsonValue> = {
      backend: 'celld',
      revision: result.revision,
    };
    if (commandId !== undefined) coordination.commandId = commandId;
    if (result.replayed) coordination.replayed = true;
    if (result.firstEventSequence !== undefined) coordination.firstEventSequence = result.firstEventSequence;
    if (result.lastEventSequence !== undefined) coordination.lastEventSequence = result.lastEventSequence;
    return coordination;
  }

  function throwRejection(result: CellCommandResult): never {
    throw new CelldError(
      result.rejection ?? rejection('VALIDATION_FAILED', 'Cell rejected the command without a rejection body'),
    );
  }

  /** Strip envelope-level keys from args to form the cell payload. */
  function payloadOf(args: Record<string, unknown>): Record<string, JsonValue> {
    const { command: _command, workspaceId: _workspaceId, backend: _backend, agentId: _agentId, ...rest } = args;
    return rest as Record<string, JsonValue>;
  }

  async function executeCelldMutation(
    operation: string,
    workspaceId: string,
    agentId: string,
    args: Record<string, unknown>,
  ): Promise<unknown> {
    const metadata = requireCommandMetadata(args, operation);
    const command = await buildCommand(operation, workspaceId, agentId, metadata, payloadOf(args));
    const result = await transport.command(workspaceId, command);
    if (result.outcome !== 'accepted') throwRejection(result);
    // Replays may legitimately rebroadcast the same event IDs — a
    // commit-before-reply retry can make this the façade's first chance to
    // hint; SSE consumers dedupe by the durable eventId (RFC 0001).
    emitCellEvents(workspaceId, command.commandId, result.events);
    return {
      ...(result.result ?? {}),
      coordination: coordinationOf(result, command.commandId),
    };
  }

  async function executeCelldQuery(
    operation: string,
    workspaceId: string,
    agentId: string,
    args: Record<string, unknown>,
  ): Promise<unknown> {
    if (operation === 'read_workspace_events') {
      // The journal endpoint carries no actor context, so membership is
      // authorized through the cell's query path first — every other query
      // already rejects non-members with NOT_WORKSPACE_MEMBER there.
      const membership = await transport.query(workspaceId, 'workspace_status', agentId, {});
      if (membership.outcome !== 'accepted') throwRejection(membership);
      const after = typeof args.after === 'number' ? args.after : 0;
      const limit = typeof args.limit === 'number' ? args.limit : 100;
      const page = await transport.events(workspaceId, after, limit);
      const last = page.events[page.events.length - 1];
      return {
        events: page.events,
        count: page.count,
        coordination: {
          backend: 'celld',
          revision: last?.aggregateRevision ?? 0,
        },
      };
    }
    const result = await transport.query(workspaceId, operation, agentId, payloadOf(args));
    if (result.outcome !== 'accepted') throwRejection(result);
    return {
      ...(result.result ?? {}),
      coordination: coordinationOf(result),
    };
  }

  async function createCelldWorkspace(agentId: string, args: Record<string, unknown>): Promise<unknown> {
    const metadata = requireCommandMetadata(args, 'create_workspace');

    // A retry with the same command ID resumes the SAME workspace: the
    // provisioning route is keyed by the creating command (RFC 0001). The
    // lookup and the claim are ONE atomic registry operation so concurrent
    // duplicates cannot each mint their own workspace.
    const route = await registry.findOrBeginProvisioning(metadata.id, `ws-${randomUUID()}`);
    const workspaceId = route.workspaceId;

    const command = await buildCommand('create_workspace', workspaceId, agentId, metadata, {
      name: String(args.name ?? ''),
      description: String(args.description ?? ''),
    });
    const result = await transport.command(workspaceId, command);
    if (result.outcome !== 'accepted') throwRejection(result);

    // Verify the cell actually holds the initialized aggregate before the
    // route goes active — an active route never falls back to filesystem.
    const snapshot = await transport.snapshot(workspaceId);
    if (snapshot.revision < 1 || snapshot.state === null) {
      throw new CelldError(
        rejection('CELLD_UNAVAILABLE', `Cell for ${workspaceId} did not verify after create (revision ${snapshot.revision})`),
      );
    }
    await registry.markActive(workspaceId);

    emitCellEvents(workspaceId, command.commandId, result.events);
    return {
      ...(result.result ?? {}),
      workspaceId,
      // Compatibility with thought-tool callers: celld workspaces carry a
      // synthetic main session; thought-branch integration is deferred.
      mainSessionId: `celld:${workspaceId}`,
      coordination: coordinationOf(result, command.commandId),
    };
  }

  return {
    async handle(agentId, operation, args, requestPrincipal) {
      const record = (args ?? {}) as Record<string, unknown>;

      if (operation === 'create_workspace' && record.backend === 'celld') {
        if (agentId === null) throw new Error('create_workspace requires a resolved agentId');
        return createCelldWorkspace(agentId, record);
      }

      const workspaceId = typeof record.workspaceId === 'string' ? record.workspaceId : undefined;
      const route = workspaceId !== undefined ? await registry.get(workspaceId) : undefined;

      if (route === undefined) {
        // Filesystem path. The five coordination operations must never reach
        // filesystem storage — reject before delegating (RFC 0001).
        if (NEW_OPERATIONS.has(operation)) {
          throw new CelldError(
            rejection(
              'OPERATION_REQUIRES_CELLD_BACKEND',
              `${operation} requires a celld-backed workspace; workspace ${workspaceId ?? '(none)'} is not routed to celld`,
            ),
          );
        }
        return inner.handle(agentId, operation, args, requestPrincipal);
      }

      // Routed workspace. Never fall back to filesystem — a provisioning
      // route is not yet writable and an unreachable cell stays celld's.
      if (route.status !== 'active') {
        throw new CelldError(
          rejection('CELLD_UNAVAILABLE', `Workspace ${route.workspaceId} is still provisioning (command ${route.commandId})`),
        );
      }
      if (!isCelldSupportedOperation(operation)) {
        throw new CelldError(
          rejection(
            'CELLD_CANARY_OPERATION_UNSUPPORTED',
            `${operation} is not part of the celld canary surface (RFC 0001 §Operation surface)`,
            { operation },
          ),
        );
      }
      if (agentId === null) throw new Error(`${operation} requires a resolved agentId`);
      if (isCelldMutation(operation)) {
        return executeCelldMutation(operation, route.workspaceId, agentId, record);
      }
      return executeCelldQuery(operation, route.workspaceId, agentId, record);
    },
  };
}
/**
 * HubReadModel (RFC 0001): the read surface behind GET /hub/workspaces and
 * GET /hub/workspaces/:id/snapshot. The filesystem implementation reproduces
 * the assembly hub-http.ts used to do inline (byte-compatible responses for
 * filesystem workspaces); the routed implementation additionally surfaces
 * celld workspaces from the route registry + cell snapshots. The registry is
 * routing authority only — workspace STATE authority for a routed workspace
 * is always the cell.
 */

import type { HubHandler } from '../hub/hub-handler.js';
import type { AgentIdentity, Channel, HubStorage, Workspace } from '../hub/hub-types.js';
import type { BackendRegistry } from './backend-registry.js';
import type { CellTransport } from './client.js';
import type { CellWorkspaceState } from './domain/state.js';

/** A workspace member joined against the global agent registry. */
export interface SnapshotAgent {
  agentId: string;
  name: string;
  role: string;
  status: string;
  joinedAt: string;
  lastSeenAt: string;
  currentWork?: string;
  profile?: string;
  registeredAt?: string;
}

export interface WorkspaceSnapshot {
  workspace: unknown;
  agents: SnapshotAgent[];
  problems: unknown[];
  proposals: unknown[];
  consensus: unknown[];
  channels: unknown[];
  coordination?: { backend: 'celld'; revision: number; maxSequence: number };
}

export interface HubReadModel {
  listWorkspaces(): Promise<unknown[]>;
  /** undefined = not found. */
  workspaceSnapshot(workspaceId: string): Promise<WorkspaceSnapshot | undefined>;
}

function joinAgents(workspace: Workspace, registry: AgentIdentity[]): SnapshotAgent[] {
  const byId = new Map(registry.map(agent => [agent.agentId, agent]));
  return workspace.agents.map(member => {
    const identity = byId.get(member.agentId);
    const joined: SnapshotAgent = {
      agentId: member.agentId,
      name: identity?.name ?? member.agentId,
      role: member.role,
      status: member.status,
      joinedAt: member.joinedAt,
      lastSeenAt: member.lastSeenAt,
    };
    if (member.currentWork !== undefined) joined.currentWork = member.currentWork;
    if (identity?.profile !== undefined) joined.profile = identity.profile;
    if (identity?.registeredAt !== undefined) joined.registeredAt = identity.registeredAt;
    return joined;
  });
}

export interface HubReadModelOptions {
  hubStorage: HubStorage;
  registry?: BackendRegistry;
  transport?: CellTransport;
}

export function createHubReadModel(options: HubReadModelOptions): HubReadModel {
  const { hubStorage, registry, transport } = options;

  async function celldWorkspaceEntries(): Promise<unknown[]> {
    if (registry === undefined || transport === undefined) return [];
    const routes = (await registry.list()).filter(route => route.status === 'active');
    const entries: unknown[] = [];
    for (const route of routes) {
      try {
        const snapshot = await transport.snapshot(route.workspaceId);
        const state = snapshot.state as CellWorkspaceState | null;
        if (state === null) continue;
        entries.push({
          id: state.workspace.id,
          name: state.workspace.name,
          description: state.workspace.description,
          createdBy: state.workspace.createdBy,
          createdAt: state.workspace.createdAt,
          updatedAt: state.workspace.updatedAt,
          mainSessionId: `celld:${state.workspace.id}`,
          agents: Object.values(state.members).map(member => ({
            agentId: member.agentId,
            role: member.role,
            joinedAt: member.joinedAt,
            status: 'online',
            lastSeenAt: member.joinedAt,
          })),
          backend: 'celld',
        });
      } catch {
        // An unreachable cell hides that workspace from the listing rather
        // than failing the whole read; the registry row still proves routing.
        entries.push({ id: route.workspaceId, backend: 'celld', unreachable: true });
      }
    }
    return entries;
  }

  return {
    async listWorkspaces() {
      const filesystem = await hubStorage.listWorkspaces();
      const celld = await celldWorkspaceEntries();
      return [...filesystem, ...celld];
    },

    async workspaceSnapshot(workspaceId) {
      const route = registry !== undefined ? await registry.get(workspaceId) : undefined;
      if (route !== undefined && transport !== undefined) {
        const snapshot = await transport.snapshot(workspaceId);
        const state = snapshot.state as CellWorkspaceState | null;
        if (state === null) return undefined;
        return {
          workspace: { ...state.workspace, id: workspaceId, mainSessionId: `celld:${workspaceId}` },
          agents: Object.values(state.members).map(member => ({
            agentId: member.agentId,
            name: member.agentId,
            role: member.role,
            status: 'online',
            joinedAt: member.joinedAt,
            lastSeenAt: member.joinedAt,
          })),
          problems: Object.values(state.problems),
          proposals: [],
          consensus: [],
          channels: Object.entries(state.channels).map(([problemId, messages]) => ({
            id: problemId,
            workspaceId,
            problemId,
            messages,
          })),
          coordination: { backend: 'celld', revision: snapshot.revision, maxSequence: snapshot.maxSequence },
        };
      }

      const workspace = await hubStorage.getWorkspace(workspaceId);
      if (!workspace) return undefined;
      const [agentRegistry, problems, proposals, consensus] = await Promise.all([
        hubStorage.getAgents(),
        hubStorage.listProblems(workspaceId),
        hubStorage.listProposals(workspaceId),
        hubStorage.listConsensusMarkers(workspaceId),
      ]);
      const channels = (
        await Promise.all(problems.map(problem => hubStorage.getChannel(workspaceId, problem.id)))
      ).filter((channel): channel is Channel => channel !== null);
      return {
        workspace,
        agents: joinAgents(workspace, agentRegistry),
        problems,
        proposals,
        consensus,
        channels,
      };
    },
  };
}

/** Narrow re-export so composition code can type the injected handler without importing src/hub deeply. */
export type { HubHandler };
/**
 * Workspace backend routing registry (RFC 0001: "`$HUB_DATA_DIR/hub/
 * workspace-backends.json` is a crash-safe routing/provisioning index only —
 * never workspace-state authority").
 *
 * Entries move provisioning → active, keyed by the creating caller's command
 * ID, so a crashed `create_workspace` retry resumes the same workspace and
 * command rather than racing a second creator into stealing it. This module
 * owns only that routing index; it has no opinion about cell state.
 *
 * Every write mirrors the fsynced-temp-file + atomic-rename pattern in
 * src/hub/hub-storage-fs.ts (`writeJson`): rename alone is not a durability
 * barrier, so the temp file's content is fsynced before the rename, and the
 * containing directory is best-effort fsynced after it so the rename itself
 * survives a crash.
 */

import { readFile, open, rename, unlink, mkdir } from 'node:fs/promises';
import { join, dirname, basename } from 'node:path';
import { randomUUID } from 'node:crypto';
import { CelldError, rejection } from './errors.js';

export interface WorkspaceRoute {
  workspaceId: string;
  backend: 'celld';
  status: 'provisioning' | 'active';
  commandId: string;
  createdAt: string;
  activatedAt?: string;
}

export interface BackendRegistry {
  get(workspaceId: string): Promise<WorkspaceRoute | undefined>;
  list(): Promise<WorkspaceRoute[]>;
  findByCommandId(commandId: string): Promise<WorkspaceRoute | undefined>;
  /**
   * Atomic find-or-create keyed by the creating command's ID. The command-ID
   * lookup and the route write happen inside ONE serialized section: two
   * concurrent first attempts with the same command ID resolve to the SAME
   * route even though each caller minted its own candidate workspace ID —
   * looking up outside the serialized section is exactly the race that
   * produced two active workspaces for one idempotency key.
   */
  findOrBeginProvisioning(commandId: string, candidateWorkspaceId: string): Promise<WorkspaceRoute>;
  markActive(workspaceId: string): Promise<void>;
}

interface RegistryDocument {
  version: 1;
  routes: Record<string, WorkspaceRoute>;
}

// =============================================================================
// Crash-safe file I/O (mirrors hub-storage-fs.ts writeJson)
// =============================================================================

async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

async function fsyncDir(dir: string): Promise<void> {
  try {
    const handle = await open(dir, 'r');
    try {
      await handle.sync();
    } finally {
      await handle.close();
    }
  } catch {
    // best-effort — some platforms/filesystems don't support fsync-ing a
    // directory handle; that does not mean the write itself failed.
  }
}

async function writeTempFile(dir: string, prefix: string, content: string): Promise<string> {
  await ensureDir(dir);
  const tmpPath = join(dir, `.${prefix}.${process.pid}.${randomUUID()}.tmp`);
  const handle = await open(tmpPath, 'w');
  try {
    await handle.writeFile(content, 'utf-8');
    await handle.sync();
  } finally {
    await handle.close();
  }
  return tmpPath;
}

async function writeRegistryDocument(path: string, doc: RegistryDocument): Promise<void> {
  const dir = dirname(path);
  const tmpPath = await writeTempFile(dir, basename(path), JSON.stringify(doc, null, 2));
  try {
    await rename(tmpPath, path);
    await fsyncDir(dir);
  } catch (err) {
    await unlink(tmpPath).catch(() => {});
    throw err;
  }
}

/**
 * A missing file is a normal first-run outcome (empty registry). Any other
 * read failure — most importantly corrupt/truncated JSON, exactly what a
 * crashed write leaves behind if it landed outside the rename barrier above
 * — throws loudly naming the file, rather than silently returning an empty
 * registry that would let a second creator steal an already-provisioning
 * workspace.
 */
async function readRegistryDocument(path: string): Promise<RegistryDocument> {
  let content: string;
  try {
    content = await readFile(path, 'utf-8');
  } catch (err) {
    if ((err as NodeJS.ErrnoException)?.code === 'ENOENT') {
      return { version: 1, routes: {} };
    }
    throw err;
  }
  try {
    return JSON.parse(content) as RegistryDocument;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`celld backend registry file is corrupt: ${path} — ${message}`);
  }
}

// =============================================================================
// Registry
// =============================================================================

export function createBackendRegistry(dataDir: string): BackendRegistry {
  const filePath = join(dataDir, 'hub', 'workspace-backends.json');

  /**
   * Every mutation runs to completion before the next one starts. Each op is
   * a read-modify-write of the WHOLE document (one file holds every route),
   * so serialization must be total across all workspaceIds, not keyed per
   * workspace — two concurrent beginProvisioning calls for DIFFERENT
   * workspaces still race on the same underlying file (mirrors the
   * `serialized` chain in src/hub/decisions.ts). Reads stay concurrent: a
   * completed rename is atomic, so a concurrent read sees either the prior
   * complete document or the new one, never a torn write.
   */
  let lastWrite: Promise<unknown> = Promise.resolve();
  function serialized<T>(op: () => Promise<T>): Promise<T> {
    const run = lastWrite.then(op, op);
    lastWrite = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async function get(workspaceId: string): Promise<WorkspaceRoute | undefined> {
    const doc = await readRegistryDocument(filePath);
    return doc.routes[workspaceId];
  }

  async function list(): Promise<WorkspaceRoute[]> {
    const doc = await readRegistryDocument(filePath);
    return Object.values(doc.routes);
  }

  async function findByCommandId(commandId: string): Promise<WorkspaceRoute | undefined> {
    const doc = await readRegistryDocument(filePath);
    return Object.values(doc.routes).find(route => route.commandId === commandId);
  }

  function findOrBeginProvisioning(commandId: string, candidateWorkspaceId: string): Promise<WorkspaceRoute> {
    return serialized(async () => {
      const doc = await readRegistryDocument(filePath);
      // Same command retrying (crash resume, or a concurrent duplicate that
      // lost the serialization race) resumes the SAME route unchanged; the
      // caller's freshly-minted candidate ID is discarded — this is the
      // crash-resume path the RFC names.
      const resumed = Object.values(doc.routes).find(route => route.commandId === commandId);
      if (resumed !== undefined) return resumed;
      const collision = doc.routes[candidateWorkspaceId];
      if (collision !== undefined) {
        throw new CelldError(
          rejection(
            'VALIDATION_FAILED',
            `workspace ${candidateWorkspaceId} is already being provisioned by command ${collision.commandId}; cannot start provisioning with command ${commandId}`,
            { workspaceId: candidateWorkspaceId, existingCommandId: collision.commandId, requestedCommandId: commandId },
          ),
        );
      }
      const route: WorkspaceRoute = {
        workspaceId: candidateWorkspaceId,
        backend: 'celld',
        status: 'provisioning',
        commandId,
        createdAt: new Date().toISOString(),
      };
      doc.routes[candidateWorkspaceId] = route;
      await writeRegistryDocument(filePath, doc);
      return route;
    });
  }

  function markActive(workspaceId: string): Promise<void> {
    return serialized(async () => {
      const doc = await readRegistryDocument(filePath);
      const existing = doc.routes[workspaceId];
      if (existing === undefined) {
        throw new CelldError(
          rejection('NOT_FOUND', `no backend route for workspace ${workspaceId}`, { workspaceId }),
        );
      }
      if (existing.status === 'active') return; // idempotent no-op
      doc.routes[workspaceId] = {
        ...existing,
        status: 'active',
        activatedAt: new Date().toISOString(),
      };
      await writeRegistryDocument(filePath, doc);
    });
  }

  return { get, list, findByCommandId, findOrBeginProvisioning, markActive };
}
/**
 * Node-side celld HTTP client (RFC 0001 §Cell command semantics, §Client
 * retry policy).
 *
 * Endpoint failover happens only on TRANSPORT failure (fetch rejection —
 * ECONNREFUSED, DNS, or an AbortSignal.timeout abort). Once a response is
 * successfully read from an endpoint, that response is DEFINITIVE: this
 * module never fails over or retries after receiving parsed bytes back,
 * because a response — success, domain rejection, or a 4xx/5xx — means the
 * request was not lost, so re-sending it or trying another node could
 * duplicate or race an already-observed effect. Probed: a non-owner node
 * transparently proxies to the owner with consistent results, so failover
 * across `HUB_CELLD_ENDPOINTS` is itself safe when it does happen.
 */

import { CelldError, rejection } from './errors.js';
import type { CelldRejection } from './errors.js';
import { hubEventV1Schema } from './contracts.js';
import type { CellCommandResult, HubCommandV1, HubEventV1 } from './contracts.js';
import type { JsonValue } from './canonical-json.js';

export interface CellSnapshot {
  workspaceId: string;
  revision: number;
  maxSequence: number;
  state: unknown;
}

export interface CellEventsPage {
  events: HubEventV1[];
  count: number;
}

export interface CellTransport {
  command(
    workspaceId: string,
    command: HubCommandV1,
  ): Promise<CellCommandResult & { events?: unknown[] }>;
  query(
    workspaceId: string,
