import type { JsonValue } from './canonical-json.js';
import type { CelldRejection } from './errors.js';

export const COMMAND_SCHEMA_VERSION = 'hub-command-v1' as const;
export const EVENT_SCHEMA_VERSION = 'hub-event-v1' as const;

