new_imports="""import type { BackendRegistry, WorkspaceRoute } from './backend-registry.js';
import type { CellTransport } from './client.js';
import type { CellWorkspaceState } from './domain/state.js';

// =============================================================================
// Cell probing shared by the HTTP read model and the routed handler
// =============================================================================

/**
 * Structural check on a snapshot body. A cell that answers with something
 * other than a workspace state (null, an empty stub, a foreign document) is
 * treated exactly like a cell that cannot be reached: the workspace is
 * listed as unreachable rather than crashing the read on a missing field.
 */
export function isCellWorkspaceState(value: unknown): value is CellWorkspaceState {
  if (value === null || typeof value !== 'object') return false;
  const state = value as Partial<CellWorkspaceState>;
  const workspace = state.workspace;
  return (
    workspace !== null &&
    typeof workspace === 'object' &&
    typeof workspace.id === 'string' &&
    state.members !== null &&
    typeof state.members === 'object' &&
    !Array.isArray(state.members)
  );
}

export interface CellWorkspaceProbe {
  route: WorkspaceRoute;
  /** null = unreachable, or the cell answered with a non-workspace body. */
  state: CellWorkspaceState | null;
}

/**
 * Snapshots every ACTIVE route concurrently. Probes never throw: an
 * unreachable cell yields `state: null` for that route only, every other
 * route is reported normally, and because the probes run in parallel the
 * whole read takes about one cell request timeout no matter how many cells
 * are slow or down. Result order follows the registry's route order.
 */
export async function probeCellWorkspaces(
  registry: BackendRegistry,
  transport: CellTransport,
): Promise<CellWorkspaceProbe[]> {
  const routes = (await registry.list()).filter(route => route.status === 'active');
  return Promise.all(
    routes.map(async (route): Promise<CellWorkspaceProbe> => {
      try {
        const snapshot = await transport.snapshot(route.workspaceId);
        return { route, state: isCellWorkspaceState(snapshot.state) ? snapshot.state : null };
      } catch {
        return { route, state: null };
      }
    }),
  );
}
